#include <stdio.h>
unsigned long factorial(unsigned int n) {
 if (n <= 1) return 1;
 return n * factorial(n - 1);
}
int main(void) {
 printf("%lu\n", factorial(5));
 return 0;
}

#include <stdio.h>
unsigned int sum_to(unsigned int n) { if (n == 0) return 0; return n + sum_to(n - 1); }
int main(void) { printf("%u\n", sum_to(5)); return 0; }
